INSERT INTO `listing` (`vin`,`seller_id`,`title`,`description`,`make`,`model`,`year`,`mileage`,`owners`,`papers`,`listing_price`,`status`,`city`,`state`,`body_type`,`image_url`,`exterior_color`,`interior_color`,`fuel_type`,`transmission`,`drivetrain`) VALUES ('D8FD4F95CD58111F1',2,'2022 Honda Civic - Clean, Low Miles','One owner, no accidents. Regular oil changes and new tires last spring. Great on gas.','Honda','Civic',2022,28500,1,'Clean',24500.00,'Available','Moscow','ID','Sedan','/images/civic.jpg','Blue','Black','Gas','Automatic','FWD'),('D8FD50686D58111F1',2,'2020 Ford Mustang 6-Speed Manual','Fun to drive manual. Recently serviced, clean title. Some light scratches on the rear bumper.','Ford','Mustang',2020,36000,2,'Clean',29995.00,'Available','Pullman','WA','Coupe','/images/mustang.jpg','Red','Black','Gas','Manual','RWD'),('D8FD50924D58111F1',2,'2019 VW Golf Hatchback','Reliable daily driver with plenty of cargo space. Heated seats and Apple CarPlay.','Volkswagen','Golf',2019,54000,3,'Rebuilt',17995.00,'Available','Spokane','WA','Hatchback','/images/golf.jpg','White','Gray','Gas','Automatic','FWD'),('D8FD50A3CD58111F1',2,'2022 Toyota RAV4 Hybrid AWD','Gets around 40 mpg. All-wheel drive, perfect for winter. Still under factory warranty.','Toyota','RAV4',2022,31000,1,'Clean',28995.00,'Available','Moscow','ID','Compact SUV','/images/rav4.jpg','Gray','Black','Hybrid','Automatic','AWD'),('D8FD50B36D58111F1',2,'2021 Honda CR-V - Great Family SUV','Spacious and comfortable. Backup camera, lane assist, and all-weather floor mats included.','Honda','CR-V',2021,46000,1,'Clean',25995.00,'Available','Coeur d\'Alene','ID','Compact SUV','/images/crv.jpg','Black','Beige','Gas','Automatic','AWD'),('D8FD510EAD58111F1',2,'2020 Chevy Tahoe - Seats 8','Third-row seating and towing package. Runs great, minor wear on the interior.','Chevrolet','Tahoe',2020,67000,2,'Clean',38995.00,'Available','Spokane','WA','Full-Size SUV','/images/tahoe.jpg','Black','Black','Gas','Automatic','4WD'),('D8FD51202D58111F1',2,'2021 Ford F-150 Crew Cab','Bed liner and tow hitch. Well maintained, service records available.','Ford','F-150',2021,49000,1,'Clean',34995.00,'Available','Lewiston','ID','Pickup','/images/f150.jpg','Blue','Gray','Gas','Automatic','4WD'),('D8FD5132ED58111F1',2,'2019 Silverado 2500HD Duramax Diesel','Heavy-duty diesel, ready for work. Gooseneck hitch installed. Mostly highway miles.','Chevrolet','Silverado 2500HD',2019,81000,3,'Clean',36500.00,'Available','Spokane','WA','Heavy-Duty Pickup','/images/silverado.jpg','Silver','Gray','Diesel','Automatic','4WD'),('D8FD51446D58111F1',2,'2022 Toyota Tacoma TRD','Off-road package. No rust, garage kept.','Toyota','Tacoma',2022,33000,1,'Clean',32995.00,'Available','Pullman','WA','Pickup','/images/tacoma.jpg','Green','Black','Gas','Automatic','4WD'),('DEMO0000000000001',2,'2021 Toyota Camry SE','Comfortable commuter with low maintenance costs. Recently detailed.','Toyota','Camry',2021,42000,1,'Clean',22995.00,'Sold','Moscow','ID','Sedan','/images/camry.jpg','Silver','Beige','Gas','Automatic','FWD');
